#!/bin/bash
# Report which declarations in `Algebra` rest on `sorry` (the axiom `sorryAx`). Bash 3.2 compatible.
#
#     scripts/axioms.sh        # summary + the dangerous ones
#     scripts/axioms.sh -v     # also list every stub
#
# A declaration is
# * a stub     if its own source contains `sorry`: expected, it's unfinished;
# * TAINTED    if it has no `sorry` of its own but uses something that does: a proof you may
#              think is finished, which is only as good as the stub it leans on.
# Declarations generated by an attribute (e.g. `ext_iff` from `@[ext]`) are reported under
# the declaration they come from.
#
# Also counts theorems and definitions (named instances included): done = sorry-free, out of all
# hand-written ones; names generated by attributes or commands are not counted.
#
# Exits 1 if anything is tainted.

cd "$(dirname "$0")/.." || exit 1

verbose=false
[ "$1" = "-v" ] && verbose=true

lake build Algebra >/dev/null 2>&1 || { echo "axioms: build failed, run 'lake build'"; exit 1; }

tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT

cat > "$tmp/Axioms.lean" <<'EOF'
import Lean
import Algebra
open Lean Elab Command in
#eval show CommandElabM Unit from do
  let env ← getEnv
  for (n, ci) in env.constants.map₁.toList do
    unless (`My).isPrefixOf n && !n.isInternal do continue
    let kind ← match ci with
      | .thmInfo _ => pure "theorem"
      | .defnInfo _ => pure "def"
      | .opaqueInfo _ => pure "def"
      | _ => continue
    if env.isProjectionFn n then continue
    let some idx := env.getModuleIdxFor? n | continue
    let path := (env.header.moduleNames[idx.toNat]!).toString.replace "." "/" ++ ".lean"
    let some r ← liftCoreM (findDeclarationRanges? n) | continue
    let src := (← IO.FS.lines path).extract (r.range.pos.line - 1) r.range.endPos.line
    -- generated by an attribute or a command (`ext_iff`, instance names, …): not counted
    unless src.any (·.contains n.getString!) do continue
    let usesSorry := (← liftCoreM (collectAxioms n)).contains ``sorryAx
    let status :=
      if src.any (·.contains "sorry") then "stub"
      else if usesSorry then "tainted"
      else "proved"
    IO.println s!"{status}\t{kind}\t{n}\t{path}\t{r.range.pos.line}"
EOF

out=$(lake env lean "$tmp/Axioms.lean" 2>&1) || { printf '%s\n' "$out"; exit 1; }

tab=$(printf '\t')
stubs=$(printf '%s\n' "$out" | grep '^stub' | sort -t "$tab" -k4,4 -k5,5n)
tainted=$(printf '%s\n' "$out" | grep '^tainted' | sort -t "$tab" -k4,4 -k5,5n)

# count STATUS KIND
count() { printf '%s\n' "$out" | grep -c "^$1$tab$2$tab"; }
nstubs=$(printf '%s' "$stubs" | grep -c .)
ntainted=$(printf '%s' "$tainted" | grep -c .)

if $verbose && [ "$nstubs" -gt 0 ]; then
  echo "stubs:"
  printf '%s\n' "$stubs" | awk -F '\t' '{ printf "  %-45s %s:%s\n", $3, $4, $5 }'
fi

for kind in theorem def; do
  p=$(count proved $kind); st=$(count stub $kind); t=$(count tainted $kind)
  printf '%-9s %4d / %-4d done  (%d stubs, %d tainted)\n' "${kind}s:" "$p" $((p + st + t)) "$st" "$t"
done

if [ "$ntainted" -gt 0 ]; then
  echo "TAINTED (no sorry of their own, but depend on one):"
  printf '%s\n' "$tainted" | awk -F '\t' '{ printf "  %-45s %s:%s\n", $3, $4, $5 }'
  echo "  find the culprit with: #print axioms <name>"
  echo "axioms: $ntainted tainted, $nstubs stubs"
  exit 1
fi

echo "axioms: ok ($nstubs stubs, nothing else depends on sorry)"
